package dev.studyforge.banking.domain; import java.util.*; public record Account(AccountId id,String holderName,Money balance){public Account{Objects.requireNonNull(id);if(holderName==null||holderName.isBlank())throw new InvalidBankingOperationException("Holder name must not be blank");Objects.requireNonNull(balance);if(balance.amount().signum()<0)throw new InvalidBankingOperationException("Opening balance must not be negative");}public Currency currency(){return balance.currency();}public Account credit(Money a){valid(a);return new Account(id,holderName,balance.add(a));}public Account debit(Money a){valid(a);if(balance.compareTo(a)<0)throw new InsufficientFundsException(id);return new Account(id,holderName,balance.subtract(a));}public void ensureCanDebit(Money a){valid(a);if(balance.compareTo(a)<0)throw new InsufficientFundsException(id);}private void valid(Money a){Objects.requireNonNull(a);if(!a.isPositive())throw new InvalidBankingOperationException("Amount must be positive");if(!currency().equals(a.currency()))throw new CurrencyMismatchException(currency(),a.currency());}public static Builder builder(AccountId id,String h,Currency c){return new Builder(id,h,c);}public static final class Builder{private final AccountId id;private final String holder;private final Currency currency;private Money opening;private Builder(AccountId i,String h,Currency c){id=i;holder=h;currency=Objects.requireNonNull(c);}public Builder openingBalance(Money b){opening=b;return this;}public Account build(){return new Account(id,holder,opening==null?Money.zero(currency):opening);}}}
